import { ChangeDetectorRef, Component, OnInit } from '@angular/core';
import { UserHttpService } from 'src/app/user-http.service';
import { AirlinesService } from 'src/app/services/airlines.service';
import { TicketsService, Tickets } from 'src/app/services/tickets.service';
import { Aircrafts } from 'src/app/services/aircrafts.service';
import { Router } from '@angular/router';

@Component({
  selector: 'app-dashboard',
  templateUrl: './dashboard.component.html',
  styleUrls: ['./dashboard.component.css']
})
export class DashboardComponent implements OnInit {
  adminRole = false;
  airlineRole = false;
  passengerRole = false;

  aircrafts: Aircrafts[] = [];
  tickets: Tickets[] = [];

  updateData: {
    name: string,
    revenue: number,
    aircrafts: Aircrafts[]
  } = {
    name: '',
    revenue: 0,
    aircrafts: []
  };


  constructor(
    private us: UserHttpService,
    private airlinesService: AirlinesService,
    private ticketsService: TicketsService,
    private router: Router,
    private cdr: ChangeDetectorRef
  ) {}

  ngOnInit(): void {
    this.adminRole = this.us.is_admin();
    this.airlineRole = this.us.is_airline();
    this.passengerRole = this.us.is_passenger();

    if (this.airlineRole) {
      const email = this.us.get_mail();

      this.airlinesService.getAircraftByMail(email).subscribe(res => {
        console.log("Aerei Ricevuti", res);
        this.aircrafts = res;
      });

      this.ticketsService.getTickets().subscribe(res => {
        console.log('Biglietti ricevuti:', res); // Debug temporaneo
        this.tickets = res;
      });
    }
  }

  updateAirlineInfo() {
    const email = this.us.get_mail();
    const data = {
      name: this.updateData.name,
      revenue: this.updateData.revenue
    };

    this.airlinesService.updateAirlines(email, data).subscribe({
      next: res => {
        console.log('Airline aggiornata:', res);
        // Aggiorna localmente in caso di cambiamenti
        this.updateData.name = res.name;
        this.updateData.revenue = res.revenue;
      },
      error: err => {
        console.error('Errore aggiornamento airline:', err);
      }
    });
  }

    // ----- Gestione Biglietti -----

  aggiungiBiglietto() {
    this.tickets.push({
      _code: '',
      user: '',
      flight: '',
      seat: '',
      price: 0,
      numBag: 0
    });
  }

  salvaBiglietto(index: number) {
    const ticket = this.tickets[index];
    if (!ticket.flight || !ticket.seat) {
      alert('Inserisci almeno volo e posto.');
      return;
    }
    this.addTicketToBackend(ticket, index);
  }

  addTicketToBackend(ticket: Tickets, index: number) {
    this.ticketsService.addTickets(ticket).subscribe({
      next: res => {
        console.log(`Biglietto per volo ${ticket.flight} aggiunto con ID ${res.id}`);
        // Aggiorna il ticket locale con il codice restituito dal backend
        this.tickets[index] = { ...ticket, _code: res.id };
      },
      error: err => {
        console.error('Errore salvataggio biglietto:', err);
      }
    });
  }

  rimuoviBiglietto(code: string, index: number) {
    if (code) {
      this.ticketsService.deleteTickets(code).subscribe({
        next: () => {
          console.log(`Biglietto ${code} eliminato correttamente`);
          this.tickets.splice(index, 1);
        },
        error: err => {
          console.error('Errore eliminazione biglietto:', err);
        }
      });
    } else {
      // Biglietto non ancora salvato: rimuovi localmente
      this.tickets.splice(index, 1);
    }
  }

  logout() {
    this.us.logout();
    this.router.navigate(['/search']);
  }
}
